                      { middleName: { [Op.like]: `%${word}%` } },
                      { lastName: { [Op.like]: `%${word}%` } },
                    ],
                  })),
                },

                // 🔥 strict full-name sequence match (best one)
                {
                  firstName: { [Op.like]: fullNameLike },
                },
                {
                  lastName: { [Op.like]: fullNameLike },
                },

                // fallback email search
                { email: { [Op.like]: `%${searchStr}%` } },
              ],
            }
          : {};


        // ---------------- ORDER SAFE ----------------
        const safeSortFields = [
          "id",
          "firstName",
          "middleName",
          "lastName",
          "email",
          "phoneNumber",
          "address",
          "registered",
        ];

        const finalSort = safeSortFields.includes(sort) ? sort : "id";

        const result = await User.findAndCountAll({
          where,
          limit: limitNumber,
          offset,
          order: [[finalSort, order as "ASC" | "DESC"]],
        });

        return res.json({
          success: true,
          data: result.rows,
          total: result.count,
          hasMore: offset + result.rows.length < result.count,
        });
      } catch (err) {
        console.error("GET /users failed", err);
        return res.status(500).json({ success: false });
      }
    });

    // ---------------- CREATE USER ----------------

    router.post("/", async (req, res) => {
      try {
        const parsed = userSchema.safeParse(req.body);

        if (!parsed.success) {
          return res.status(400).json({
            success: false,
            errors: parsed.error.flatten(),
          });
        }

        const user = await User.create({
          ...parsed.data,
          registered: new Date(),
        });

        return res.status(201).json({ success: true, data: user });
      } catch (err) {
        return res.status(500).json({ success: false });
      }
    });

    // ---------------- UPDATE USER ----------------
    router.put("/:id", async (req, res) => {
      try {
        const { id } = req.params;

        const user = await User.findByPk(id);

        if (!user) {
          return res.status(404).json({
            success: false,
            message: "User not found",
          });
        }

        const parsed = userSchema.safeParse(req.body);
        if (!parsed.success) {
          return res.status(400).json({
            success: false,
            errors: parsed.error.flatten(),
          });
        }

        await user.update(parsed.data);
        return res.json({
          success: true,
          data: user,
        });
      } catch (err) {
        console.error("UPDATE user failed", err);
        return res.status(500).json({ success: false });
      }
    });

    // ---------------- DELETE USER ----------------
    router.delete("/:id", async (req, res) => {
      try {
        const { id } = req.params;

        const deleted = await User.destroy({
          where: { id },
        });

        if (!deleted) {
          return res.status(404).json({
            success: false,
            message: "User not found",
          });
        }

        return res.json({
          success: true,
        });
      } catch (err) {
        console.error("DELETE user failed", err);
        return res.status(500).json({ success: false });
      }
    });

    return router;
  },
};

export default UsersRouter;

